Given the following singly linked list in python, create a doubly linked list and provide an approachable explaination for beginners as to the differences between the two, and what code you wrote to make the singly linked list a doubly linked list.


```python


class Node:
    def __init__(self, data):
        self.data = data
        self.next = None


class LinkedList:

    def __init__(self):
        self.head = None

    def append(self, new_data):
        new_node = Node(new_data)
        new_node.next = self.head
        self.head = new_node

    def find(self, item):
        current = self.head

        found = False
        counter = 0

        while current != None and not found:
            if current.data == item:
                found = True
            else:
                current = current.next
                counter += 1

        if found:
            return counter
        else:
            return -1

    def length(self):
        if self.head == None:
            return 0
        else:
            counter = 1
            current = self.head
            while (current.next):
                current = current.next
                counter += 1
            return counter

    def remove(self, item):
        current = self.head
        previous = None
        found = False
        while not found:
            if current.data == item:
                found = True
            else:
                previous = current
                current = current.next

        if previous == None:
            self.head = current.next
        else:
            previous.next = current.next

    def print_nodes(self):
        current = self.head

        if current == None:
            print('The linked list is empty.')
        else:
            for i in range(self.length()):
                print(f'Node {i}: {current.data}')
                current = current.next

